interface Printable { void print(); }
class Page implements Printable { public void print() { System.out.println("Page"); } }
public class Main { public static void main(String[] args) { Printable p = new Page(); p.print(); } }

interface Fly { void move(); }
interface Swim { void moveInWater(); }
class Duck implements Fly, Swim { public void move() { System.out.println("Fly"); } public void moveInWater() { System.out.println("Swim"); } }
public class Main { public static void main(String[] args) { Duck d = new Duck(); d.move(); d.moveInWater(); } }

interface Payable { int amount(); }
class Invoice implements Payable { public int amount() { return 250; } }
public class Main { static void show(Payable p) { System.out.println(p.amount()); } public static void main(String[] args) { show(new Invoice()); } }

interface Welcome { default void greet() { System.out.println("Welcome"); } }
class Member implements Welcome { }
public class Main { public static void main(String[] args) { new Member().greet(); } }
